using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _service;

    public NotificationServiceTests()
    {
        _service = new NotificationService();
        // Drain any residual notifications from the static queue
        while (_service.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain after each test to avoid cross-test pollution
        while (_service.ReceiveNotification() != null) { }
        _service.Dispose();
    }

    [Fact]
    public void SendNotification_EnqueuesNotification_CanBeReceived()
    {
        _service.SendNotification("Student", "42", EntityOperation.CREATE, "TestUser");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("TestUser", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithDisplayName_GeneratesCorrectCreateMessage()
    {
        _service.SendNotification("Student", "1", "John Smith", EntityOperation.CREATE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("New Student 'John Smith' has been created", notification.Message);
    }

    [Fact]
    public void SendNotification_WithDisplayName_GeneratesCorrectUpdateMessage()
    {
        _service.SendNotification("Course", "101", "Chemistry", EntityOperation.UPDATE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Course 'Chemistry' has been updated", notification.Message);
    }

    [Fact]
    public void SendNotification_WithDisplayName_GeneratesCorrectDeleteMessage()
    {
        _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Department 'Engineering' has been deleted", notification.Message);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
    {
        _service.SendNotification("Student", "99", EntityOperation.CREATE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("New Student (ID: 99) has been created", notification.Message);
    }

    [Fact]
    public void SendNotification_WithNullDisplayName_UsesIdInMessage()
    {
        _service.SendNotification("Instructor", "7", null, EntityOperation.UPDATE, "System");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Instructor (ID: 7) has been updated", notification.Message);
    }

    [Fact]
    public void SendNotification_WithWhitespaceDisplayName_UsesIdInMessage()
    {
        _service.SendNotification("Instructor", "7", "   ", EntityOperation.DELETE, "System");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Instructor (ID: 7) has been deleted", notification.Message);
    }

    [Fact]
    public void SendNotification_DefaultsCreatedByToSystem_WhenUserNameIsNull()
    {
        _service.SendNotification("Student", "1", EntityOperation.CREATE);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToRecentTime()
    {
        var beforeSend = DateTime.Now.AddSeconds(-1);
        _service.SendNotification("Student", "1", EntityOperation.CREATE);
        var afterSend = DateTime.Now.AddSeconds(1);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, beforeSend, afterSend);
    }

    [Fact]
    public void ReceiveNotification_ReturnsNull_WhenQueueIsEmpty()
    {
        var notification = _service.ReceiveNotification();
        Assert.Null(notification);
    }

    [Fact]
    public void ReceiveNotification_ReturnsFIFOOrder()
    {
        _service.SendNotification("Student", "1", "First", EntityOperation.CREATE);
        _service.SendNotification("Student", "2", "Second", EntityOperation.CREATE);
        _service.SendNotification("Student", "3", "Third", EntityOperation.CREATE);

        var first = _service.ReceiveNotification();
        var second = _service.ReceiveNotification();
        var third = _service.ReceiveNotification();
        var fourth = _service.ReceiveNotification();

        Assert.Equal("1", first.EntityId);
        Assert.Equal("2", second.EntityId);
        Assert.Equal("3", third.EntityId);
        Assert.Null(fourth);
    }

    [Fact]
    public void SendNotification_SetsIsReadToFalse()
    {
        _service.SendNotification("Student", "1", EntityOperation.CREATE);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op for in-memory implementation, should not throw
        var exception = Record.Exception(() => _service.MarkAsRead(999));
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_OverloadWithoutDisplayName_CallsFiveParameterOverload()
    {
        _service.SendNotification("Course", "500", EntityOperation.DELETE, "TestAdmin");

