using Xunit;

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    private IQueryable<int> CreateTestSource(int count)
    {
        return Enumerable.Range(1, count).AsQueryable();
    }

    [Fact]
    public void Create_ReturnsCorrectPageOfItems()
    {
        var source = CreateTestSource(25);

        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(11, result[0]); // Items 11-20
        Assert.Equal(20, result[9]);
    }

    [Fact]
    public void Create_FirstPage_ContainsFirstItems()
    {
        var source = CreateTestSource(25);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(1, result[0]);
        Assert.Equal(10, result[9]);
    }

    [Fact]
    public void Create_LastPage_ContainsRemainingItems()
    {
        var source = CreateTestSource(25);

        var result = PaginatedList<int>.Create(source, pageIndex: 3, pageSize: 10);

        Assert.Equal(5, result.Count);
        Assert.Equal(21, result[0]);
        Assert.Equal(25, result[4]);
    }

    [Fact]
    public void TotalPages_CalculatedWithCeilingDivision()
    {
        var source = CreateTestSource(25);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Equal(3, result.TotalPages); // ceil(25/10) = 3
    }

    [Fact]
    public void TotalPages_ExactDivision()
    {
        var source = CreateTestSource(20);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Equal(2, result.TotalPages); // 20/10 = 2
    }

    [Fact]
    public void TotalPages_SinglePage()
    {
        var source = CreateTestSource(5);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Equal(1, result.TotalPages);
    }

    [Fact]
    public void PageIndex_IsSet()
    {
        var source = CreateTestSource(25);

        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

        Assert.Equal(2, result.PageIndex);
    }

    [Fact]
    public void HasPreviousPage_ReturnsFalse_ForFirstPage()
    {
        var source = CreateTestSource(25);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_ReturnsTrue_ForSecondPage()
    {
        var source = CreateTestSource(25);

        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_ReturnsTrue_WhenNotOnLastPage()
    {
        var source = CreateTestSource(25);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_ReturnsFalse_WhenOnLastPage()
    {
        var source = CreateTestSource(25);

        var result = PaginatedList<int>.Create(source, pageIndex: 3, pageSize: 10);

        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void HasPreviousPage_AndHasNextPage_BothTrue_ForMiddlePage()
    {
        var source = CreateTestSource(30);

        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

        Assert.True(result.HasPreviousPage);
        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void SingleItemSource_HasNoPreviousOrNextPage()
    {
        var source = CreateTestSource(1);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
        Assert.Equal(1, result.TotalPages);
        Assert.Single(result);
    }

    [Fact]
    public void EmptySource_ReturnsEmptyList()
    {
        var source = Enumerable.Empty<int>().AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
        Assert.Equal(1, result.PageIndex);
    }

    [Fact]
    public void Constructor_AddRangeAddsItems()
    {
        var items = new List<int> { 10, 20, 30 };

        var list = new PaginatedList<int>(items, count: 30, pageIndex: 1, pageSize: 10);

        Assert.Equal(3, list.Count);
        Assert.Contains(10, list);
        Assert.Contains(20, list);
        Assert.Contains(30, list);
        Assert.Equal(3, list.TotalPages);
    }

    [Fact]
    public void PageSize_LargerThanSource_ReturnsSinglePage()
    {
        var source = CreateTestSource(3);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 100);

        Assert.Equal(3, result.Count);
        Assert.Equal(1, result.TotalPages);
        Assert.False(result.HasNextPage);
        Assert.False(result.HasPreviousPage);
    }
}

