using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data;

public class DbInitializerTests
{
    private SchoolContext CreateContext(string dbName = null)
    {
        return TestDbContextFactory.Create(dbName ?? Guid.NewGuid().ToString());
    }

    [Fact]
    public void Initialize_SeedsStudents()
    {
        using var context = CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(8, context.Students.Count());
    }

    [Fact]
    public void Initialize_SeedsInstructors()
    {
        using var context = CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(5, context.Instructors.Count());
    }

    [Fact]
    public void Initialize_SeedsDepartments()
    {
        using var context = CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(4, context.Departments.Count());
    }

    [Fact]
    public void Initialize_SeedsCourses()
    {
        using var context = CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(7, context.Courses.Count());
    }

    [Fact]
    public void Initialize_SeedsEnrollments()
    {
        using var context = CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(11, context.Enrollments.Count());
    }

    [Fact]
    public void Initialize_SeedsOfficeAssignments()
    {
        using var context = CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(3, context.OfficeAssignments.Count());
    }

    [Fact]
    public void Initialize_SeedsCourseAssignments()
    {
        using var context = CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(8, context.CourseAssignments.Count());
    }

    [Fact]
    public void Initialize_IsIdempotent_DoesNotReseedWhenStudentsExist()
    {
        using var context = CreateContext();

        // First seed
        DbInitializer.Initialize(context);
        var initialStudentCount = context.Students.Count();

        // Second call should be a no-op
        DbInitializer.Initialize(context);

        Assert.Equal(initialStudentCount, context.Students.Count());
    }

    [Fact]
    public void Initialize_StudentNames_AreCorrect()
    {
        using var context = CreateContext();

        DbInitializer.Initialize(context);

        var studentNames = context.Students.Select(s => s.LastName).OrderBy(n => n).ToList();
        Assert.Contains("Alexander", studentNames);
        Assert.Contains("Alonso", studentNames);
        Assert.Contains("Anand", studentNames);
        Assert.Contains("Barzdukas", studentNames);
        Assert.Contains("Li", studentNames);
        Assert.Contains("Justice", studentNames);
        Assert.Contains("Norman", studentNames);
        Assert.Contains("Olivetto", studentNames);
    }

    [Fact]
    public void Initialize_DepartmentNames_AreCorrect()
    {
        using var context = CreateContext();

        DbInitializer.Initialize(context);

        var deptNames = context.Departments.Select(d => d.Name).OrderBy(n => n).ToList();
        Assert.Equal(new[] { "Economics", "Engineering", "English", "Mathematics" }, deptNames);
    }

    [Fact]
    public void Initialize_Courses_HaveCorrectDepartmentAssignment()
    {
        using var context = CreateContext();

        DbInitializer.Initialize(context);

        var chemistry = context.Courses.Include(c => c.Department).Single(c => c.Title == "Chemistry");
        Assert.Equal("Engineering", chemistry.Department.Name);

        var calculus = context.Courses.Include(c => c.Department).Single(c => c.Title == "Calculus");
        Assert.Equal("Mathematics", calculus.Department.Name);
    }

    [Fact]
    public void Initialize_Enrollments_HaveGrades()
    {
        using var context = CreateContext();

        DbInitializer.Initialize(context);

        var enrollmentWithGradeA = context.Enrollments.FirstOrDefault(e => e.Grade == Grade.A);
        Assert.NotNull(enrollmentWithGradeA);

        // Arturo Anand's Chemistry enrollment has no grade
        var anandId = context.Students.Single(s => s.LastName == "Anand").ID;
        var chemId = context.Courses.Single(c => c.Title == "Chemistry").CourseID;
        var noGradeEnrollment = context.Enrollments.Single(e => e.StudentID == anandId && e.CourseID == chemId);
        Assert.Null(noGradeEnrollment.Grade);
    }
}

