using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new StudentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Student SeedStudent(string lastName = "Doe", string firstName = "Jane", DateTime? enrollmentDate = null)
    {
        var student = new Student
        {
            LastName = lastName,
            FirstMidName = firstName,
            EnrollmentDate = enrollmentDate ?? new DateTime(2024, 9, 1)
        };
        _context.Students.Add(student);
        _context.SaveChanges();
        return student;
    }

    private void SeedMultipleStudents()
    {
        _context.Students.AddRange(
            new Student { LastName = "Anderson", FirstMidName = "Alice", EnrollmentDate = new DateTime(2023, 1, 15) },
            new Student { LastName = "Brown", FirstMidName = "Bob", EnrollmentDate = new DateTime(2024, 3, 20) },
            new Student { LastName = "Clark", FirstMidName = "Carol", EnrollmentDate = new DateTime(2022, 9, 1) },
            new Student { LastName = "Davis", FirstMidName = "Dan", EnrollmentDate = new DateTime(2024, 6, 15) },
            new Student { LastName = "Evans", FirstMidName = "Eve", EnrollmentDate = new DateTime(2023, 9, 1) }
        );
        _context.SaveChanges();
    }

    // --- Index tests ---

    [Fact]
    public void Index_ReturnsViewResult()
    {
        SeedStudent();

        var result = _controller.Index(null, null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
    }

    [Fact]
    public void Index_DefaultSort_OrdersByLastNameAscending()
    {
        SeedMultipleStudents();

        var result = _controller.Index(null, null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Anderson", model[0].LastName);
        Assert.Equal("Evans", model[model.Count - 1].LastName);
    }

    [Fact]
    public void Index_NameDescSort_OrdersByLastNameDescending()
    {
        SeedMultipleStudents();

        var result = _controller.Index("name_desc", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Evans", model[0].LastName);
        Assert.Equal("Anderson", model[model.Count - 1].LastName);
    }

    [Fact]
    public void Index_DateSort_OrdersByEnrollmentDateAscending()
    {
        SeedMultipleStudents();

        var result = _controller.Index("Date", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        // Clark (2022) should be first
        Assert.Equal("Clark", model[0].LastName);
    }

    [Fact]
    public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
    {
        SeedMultipleStudents();

        var result = _controller.Index("date_desc", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        // Davis (2024-06-15) or Brown (2024-03-20) should be first
        Assert.Equal("Davis", model[0].LastName);
    }

    [Fact]
    public void Index_SearchByLastName_FiltersResults()
    {
        SeedMultipleStudents();

        var result = _controller.Index(null, null, "Brown", null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Brown", model[0].LastName);
    }

    [Fact]
    public void Index_SearchByFirstName_FiltersResults()
    {
        SeedMultipleStudents();

        var result = _controller.Index(null, null, "Alice", null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Anderson", model[0].LastName);
    }

    [Fact]
    public void Index_SearchResets_PageTo1()
    {
        SeedMultipleStudents();

        var result = _controller.Index(null, null, "Anderson", null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_UsesCurrentFilter_WhenSearchStringIsNull()
    {
        SeedMultipleStudents();

        var result = _controller.Index(null, "Brown", null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
    }

    [Fact]
    public void Index_Pagination_LimitsTo10PerPage()
    {
        // Add 15 students
        for (int i = 0; i < 15; i++)
        {
            _context.Students.Add(new Student
            {
                LastName = $"Student{i:D2}",
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(2024, 1, 1)
            });
        }
        _context.SaveChanges();

        var result = _controller.Index(null, null, null, 1);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal(10, model.Count);
        Assert.True(model.HasNextPage);
        Assert.False(model.HasPreviousPage);
    }

    [Fact]
    public void Index_SetsViewBagProperties()
    {
        SeedStudent();

        var result = _controller.Index("Date", null, "test", null);

