using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly Mock<IWebHostEnvironment> _envMock;
    private readonly Mock<ILogger<CoursesController>> _loggerMock;
    private readonly CoursesController _controller;

    public CoursesControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _envMock = new Mock<IWebHostEnvironment>();
        _envMock.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
        _envMock.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _loggerMock = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _envMock.Object, _loggerMock.Object);

        SeedDepartment();
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Department SeedDepartment()
    {
        if (_context.Departments.Any()) return _context.Departments.First();
        var dept = new Department
        {
            Name = "Engineering",
            Budget = 350000,
            StartDate = new DateTime(2007, 9, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Course SeedCourse(int courseId = 1050, string title = "Chemistry", int credits = 3)
    {
        var dept = _context.Departments.First();
        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = credits,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    // --- Index ---

    [Fact]
    public void Index_ReturnsViewWithCourses()
    {
        SeedCourse();

        var result = _controller.Index();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<Course>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Chemistry", model[0].Title);
    }

    [Fact]
    public void Index_EmptyDb_ReturnsEmptyList()
    {
        var result = _controller.Index();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<Course>>(viewResult.Model);
        Assert.Empty(model);
    }

    // --- Details ---

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithCourse()
    {
        var course = SeedCourse();

        var result = _controller.Details(course.CourseID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Course>(viewResult.Model);
        Assert.Equal("Chemistry", model.Title);
        Assert.Equal(3, model.Credits);
    }

    // --- Create (GET) ---

    [Fact]
    public void Create_Get_ReturnsViewWithNewCourse()
    {
        var result = _controller.Create();

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.IsType<Course>(viewResult.Model);
    }

    // --- Create (POST) ---

    [Fact]
    public void Create_Post_ValidCourse_NoImage_RedirectsToIndex()
    {
        var course = new Course
        {
            CourseID = 2000,
            Title = "Physics",
            Credits = 4,
            DepartmentID = _context.Departments.First().DepartmentID
        };

        var result = _controller.Create(course, null);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_ValidCourse_NoImage_SavesToDB()
    {
        var course = new Course
        {
            CourseID = 3000,
            Title = "Biology",
            Credits = 3,
            DepartmentID = _context.Departments.First().DepartmentID
        };

        _controller.Create(course, null);

        var saved = _context.Courses.Find(3000);
        Assert.NotNull(saved);
        Assert.Equal("Biology", saved.Title);
        Assert.Equal(3, saved.Credits);
    }

    [Fact]
    public void Create_Post_InvalidExtension_ReturnsViewWithError()
    {
        var course = new Course
        {
            CourseID = 4000,
            Title = "Art",
            Credits = 2,
            DepartmentID = _context.Departments.First().DepartmentID
        };
        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("test.exe");
        fileMock.Setup(f => f.Length).Returns(1024);

        var result = _controller.Create(course, fileMock.Object);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var errors = _controller.ModelState["teachingMaterialImage"].Errors;
        Assert.Contains(errors, e => e.ErrorMessage.Contains("valid image file"));
    }

    [Fact]
    public void Create_Post_FileTooLarge_ReturnsViewWithError()
    {
        var course = new Course
        {
            CourseID = 5000,
            Title = "Music",
            Credits = 2,
            DepartmentID = _context.Departments.First().DepartmentID
        };
        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("test.jpg");
        fileMock.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB > 5MB limit

        var result = _controller.Create(course, fileMock.Object);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var errors = _controller.ModelState["teachingMaterialImage"].Errors;
        Assert.Contains(errors, e => e.ErrorMessage.Contains("5MB"));
    }

    [Theory]
    [InlineData(".jpg")]
    [InlineData(".jpeg")]
    [InlineData(".png")]
    [InlineData(".gif")]
    [InlineData(".bmp")]
    public void Create_Post_AllowedExtensions_AreAccepted(string extension)
    {
        var course = new Course
        {
            CourseID = 6000 + Math.Abs(extension.GetHashCode() % 999),
            Title = $"Course{extension}",
            Credits = 3,
            DepartmentID = _context.Departments.First().DepartmentID
        };
        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns($"image{extension}");
        fileMock.Setup(f => f.Length).Returns(1024);
        fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = _controller.Create(course, fileMock.Object);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_ValidImage_SetsTMImagePath()
    {
        var course = new Course
        {
            CourseID = 7000,
            Title = "ImageTest",
            Credits = 3,
            DepartmentID = _context.Departments.First().DepartmentID
        };
        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("test.png");
        fileMock.Setup(f => f.Length).Returns(1024);
        fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        _controller.Create(course, fileMock.Object);

        var saved = _context.Courses.Find(7000);
        Assert.NotNull(saved);
        Assert.StartsWith("/Uploads/TeachingMaterials/course_7000_", saved.TeachingMaterialImagePath);
        Assert.EndsWith(".png", saved.TeachingMaterialImagePath);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course
        {
            CourseID = 8000,
            Title = "",
            Credits = 3,
            DepartmentID = _context.Departments.First().DepartmentID
        };

        var result = _controller.Create(course, null);

        Assert.IsType<ViewResult>(result);
    }

    [Theory]
    [InlineData(".exe")]
    [InlineData(".pdf")]
    [InlineData(".docx")]
    [InlineData(".svg")]
    public void Create_Post_DisallowedExtensions_AreRejected(string extension)
    {
        var course = new Course
        {
            CourseID = 9000 + Math.Abs(extension.GetHashCode() % 999),
            Title = $"Bad{extension}",
            Credits = 3,
            DepartmentID = _context.Departments.First().DepartmentID
        };
        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns($"file{extension}");
        fileMock.Setup(f => f.Length).Returns(1024);

        var result = _controller.Create(course, fileMock.Object);

        Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Create_Post_ExactlyAtSizeLimit_IsAccepted()
    {
        var course = new Course
        {
            CourseID = 7700,
            Title = "ExactLimit",
            Credits = 3,
            DepartmentID = _context.Departments.First().DepartmentID
        };
        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("exact.jpg");
        fileMock.Setup(f => f.Length).Returns(5 * 1024 * 1024); // Exactly 5MB
        fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = _controller.Create(course, fileMock.Object);

        // Exactly 5MB should pass the > check (not >=)
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    // --- Edit (GET) ---

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_NotFound_ReturnsNotFound()
    {
        var result = _controller.Edit(99999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsView()
    {
        var course = SeedCourse();

        var result = _controller.Edit(course.CourseID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Course>(viewResult.Model);
        Assert.Equal(course.CourseID, model.CourseID);
    }

    // --- Edit (POST) ---

    [Fact]
    public void Edit_Post_ValidCourse_NoImage_RedirectsToIndex()
    {
        var course = SeedCourse(courseId: 1111);
        _context.Entry(course).State = EntityState.Detached;

