using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class DepartmentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly DepartmentsController _controller;

    public DepartmentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new DepartmentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Department SeedDepartment(string name = "Engineering", decimal budget = 350000)
    {
        var dept = new Department
        {
            Name = name,
            Budget = budget,
            StartDate = new DateTime(2007, 9, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Instructor SeedInstructor(string lastName = "Smith", string firstName = "John")
    {
        var instructor = new Instructor
        {
            LastName = lastName,
            FirstMidName = firstName,
            HireDate = new DateTime(2020, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    // --- Index ---

    [Fact]
    public void Index_ReturnsViewWithDepartments()
    {
        SeedDepartment();

        var result = _controller.Index();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Engineering", model[0].Name);
    }

    [Fact]
    public void Index_EmptyDb_ReturnsEmptyList()
    {
        var result = _controller.Index();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
        Assert.Empty(model);
    }

    [Fact]
    public void Index_MultipleDepartments_ReturnsAll()
    {
        SeedDepartment("Engineering");
        SeedDepartment("Mathematics", 100000);
        SeedDepartment("English", 200000);

        var result = _controller.Index();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
        Assert.Equal(3, model.Count);
    }

    // --- Details ---

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_NotFound_ReturnsNotFound()
    {
        var result = _controller.Details(99999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithDepartment()
    {
        var dept = SeedDepartment();

        var result = _controller.Details(dept.DepartmentID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Department>(viewResult.Model);
        Assert.Equal("Engineering", model.Name);
        Assert.Equal(350000, model.Budget);
    }

    // --- Create (GET) ---

    [Fact]
    public void Create_Get_ReturnsView()
    {
        SeedInstructor(); // Need at least one instructor for the SelectList

        var result = _controller.Create();

        Assert.IsType<ViewResult>(result);
    }

    // --- Create (POST) ---

    [Fact]
    public void Create_Post_ValidDepartment_RedirectsToIndex()
    {
        var dept = new Department
        {
            Name = "Science",
            Budget = 250000,
            StartDate = new DateTime(2024, 1, 1)
        };

        var result = _controller.Create(dept);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_ValidDepartment_SavesToDB()
    {
        var dept = new Department
        {
            Name = "Physics",
            Budget = 150000,
            StartDate = new DateTime(2024, 6, 1)
        };

        _controller.Create(dept);

        var saved = _context.Departments.Single(d => d.Name == "Physics");
        Assert.Equal(150000, saved.Budget);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        SeedInstructor();
        _controller.ModelState.AddModelError("Name", "Required");
        var dept = new Department
        {
            Name = "",
            Budget = 0,
            StartDate = DateTime.Now
        };

        var result = _controller.Create(dept);

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void Create_Post_WithInstructor_SavesDepartment()
    {
        var instructor = SeedInstructor();
        var dept = new Department
        {
            Name = "CS",
            Budget = 500000,
            StartDate = new DateTime(2024, 1, 1),
            InstructorID = instructor.ID
        };

        _controller.Create(dept);

        var saved = _context.Departments.Include(d => d.Administrator)
            .Single(d => d.Name == "CS");
        Assert.Equal(instructor.ID, saved.InstructorID);
    }

    // --- Edit (GET) ---

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_NotFound_ReturnsNotFound()
    {
        var result = _controller.Edit(99999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithDepartment()
    {
        var dept = SeedDepartment();
        SeedInstructor();

        var result = _controller.Edit(dept.DepartmentID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Department>(viewResult.Model);
        Assert.Equal("Engineering", model.Name);
    }

    // --- Edit (POST) ---

    [Fact]
    public void Edit_Post_ValidDepartment_RedirectsToIndex()
    {
        var dept = SeedDepartment();
        SeedInstructor();
        _context.Entry(dept).State = EntityState.Detached;

        dept.Name = "Updated Engineering";

        var result = _controller.Edit(dept);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_ValidDepartment_UpdatesDatabase()
    {
        var dept = SeedDepartment();
        SeedInstructor();
        _context.Entry(dept).State = EntityState.Detached;

        dept.Name = "New Name";
        dept.Budget = 999999;

        _controller.Edit(dept);

        var updated = _context.Departments.Find(dept.DepartmentID);
        Assert.Equal("New Name", updated.Name);
        Assert.Equal(999999, updated.Budget);
    }

    [Fact]
    public void Edit_Post_InvalidModelState_ReturnsView()
    {
        var dept = SeedDepartment();
        SeedInstructor();
        _context.Entry(dept).State = EntityState.Detached;
        _controller.ModelState.AddModelError("Name", "Required");

        var result = _controller.Edit(dept);

        Assert.IsType<ViewResult>(result);
    }

    // --- Delete (GET) ---

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_NotFound_ReturnsNotFound()
    {
        var result = _controller.Delete(99999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsView()
    {
        var dept = SeedDepartment();

        var result = _controller.Delete(dept.DepartmentID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Department>(viewResult.Model);
        Assert.Equal(dept.DepartmentID, model.DepartmentID);
    }

    // --- DeleteConfirmed ---

    [Fact]
    public void DeleteConfirmed_RemovesDepartmentFromDb()
    {
        var dept = SeedDepartment();

        _controller.DeleteConfirmed(dept.DepartmentID);

        Assert.Null(_context.Departments.Find(dept.DepartmentID));
    }

    [Fact]
    public void DeleteConfirmed_RedirectsToIndex()
    {
        var dept = SeedDepartment();

        var result = _controller.DeleteConfirmed(dept.DepartmentID);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }
}

