using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new InstructorsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Instructor SeedInstructor(string lastName = "Smith", string firstName = "John",
        List<CourseAssignment> courseAssignments = null)
    {
        var instructor = new Instructor
        {
            LastName = lastName,
            FirstMidName = firstName,
            HireDate = new DateTime(2020, 1, 1),
            CourseAssignments = courseAssignments ?? new List<CourseAssignment>()
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    private Department SeedDepartment(string name = "Engineering", int? instructorId = null)
    {
        var dept = new Department
        {
            Name = name,
            Budget = 350000,
            StartDate = new DateTime(2007, 9, 1),
            InstructorID = instructorId
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Course SeedCourse(int courseId, string title = "TestCourse")
    {
        if (!_context.Departments.Any())
            SeedDepartment();
        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = 3,
            DepartmentID = _context.Departments.First().DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    // --- Index ---

    [Fact]
    public void Index_NoParams_ReturnsViewWithInstructors()
    {
        SeedInstructor("Alpha", "A");
        SeedInstructor("Beta", "B");

        var result = _controller.Index(null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_WithInstructorId_PopulatesCourses()
    {
        SeedDepartment();
        var course = SeedCourse(100, "Math");
        var instructor = SeedInstructor("InstrA", "A");
        var ca = new CourseAssignment { InstructorID = instructor.ID, CourseID = course.CourseID };
        _context.CourseAssignments.Add(ca);
        _context.SaveChanges();

        var result = _controller.Index(instructor.ID, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        Assert.NotNull(model.Courses);
        Assert.Single(model.Courses);
        Assert.Equal("Math", model.Courses.First().Title);
    }

    [Fact]
    public void Index_OrdersByLastName()
    {
        SeedInstructor("Zeta", "Z");
        SeedInstructor("Alpha", "A");

        var result = _controller.Index(null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        var names = model.Instructors.Select(i => i.LastName).ToList();
        Assert.Equal("Alpha", names[0]);
        Assert.Equal("Zeta", names[1]);
    }

    // --- Details ---

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_NotFound_ReturnsNotFound()
    {
        var result = _controller.Details(99999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithInstructor()
    {
        var instructor = SeedInstructor();

        var result = _controller.Details(instructor.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.Equal("Smith", model.LastName);
    }

    // --- Create (GET) ---

    [Fact]
    public void Create_Get_ReturnsViewWithInstructor()
    {
        var result = _controller.Create();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.NotNull(model.CourseAssignments);
        Assert.Empty(model.CourseAssignments);
    }

    // --- Create (POST) ---

    [Fact]
    public void Create_Post_ValidInstructor_RedirectsToIndex()
    {
        var instructor = new Instructor
        {
            LastName = "NewInstr",
            FirstMidName = "Test",
            HireDate = new DateTime(2024, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_ValidInstructor_SavesToDB()
    {
        var instructor = new Instructor
        {
            LastName = "Created",
            FirstMidName = "Just",
            HireDate = new DateTime(2024, 6, 15),
            CourseAssignments = new List<CourseAssignment>()
        };

        _controller.Create(instructor, null);

        var saved = _context.Instructors.Single(i => i.LastName == "Created");
        Assert.Equal("Just", saved.FirstMidName);
        Assert.Equal(new DateTime(2024, 6, 15), saved.HireDate);
    }

    [Fact]
    public void Create_Post_WithSelectedCourses_AddsCourseAssignments()
    {
        SeedDepartment();
        SeedCourse(200, "Physics");
        SeedCourse(201, "Chemistry");

        var instructor = new Instructor
        {
            LastName = "WithCourses",
            FirstMidName = "Prof",
            HireDate = new DateTime(2024, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        var selectedCourses = new[] { "200", "201" };

        _controller.Create(instructor, selectedCourses);

        var saved = _context.Instructors
            .Include(i => i.CourseAssignments)
            .Single(i => i.LastName == "WithCourses");
        Assert.Equal(2, saved.CourseAssignments.Count);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor
        {
            LastName = "",
            FirstMidName = "",
            HireDate = DateTime.Now,
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null);

        Assert.IsType<ViewResult>(result);
    }

    // --- Edit (GET) ---

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithInstructor()
    {
        var instructor = SeedInstructor();

        var result = _controller.Edit(instructor.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.Equal(instructor.ID, model.ID);
    }

    // --- Delete (GET) ---

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_NotFound_ReturnsNotFound()
    {
        var result = _controller.Delete(99999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsView()
    {
        var instructor = SeedInstructor();

        var result = _controller.Delete(instructor.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.Equal(instructor.ID, model.ID);
    }

    // --- DeleteConfirmed ---

    [Fact]
    public void DeleteConfirmed_RemovesInstructorFromDb()
    {
        var instructor = SeedInstructor();

        _controller.DeleteConfirmed(instructor.ID);

        Assert.Null(_context.Instructors.Find(instructor.ID));
    }

    [Fact]
    public void DeleteConfirmed_RedirectsToIndex()
    {
        var instructor = SeedInstructor();

        var result = _controller.DeleteConfirmed(instructor.ID);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void DeleteConfirmed_ClearsDepartmentAdministrator()
    {
        var instructor = SeedInstructor();
        var dept = SeedDepartment("TestDept", instructor.ID);

        _controller.DeleteConfirmed(instructor.ID);

        var updatedDept = _context.Departments.Find(dept.DepartmentID);
        Assert.Null(updatedDept.InstructorID);
    }
}

