using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class HomeControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly HomeController _controller;

    public HomeControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new HomeController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Index_ReturnsViewResult()
    {
        var result = _controller.Index();
        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void Contact_ReturnsViewResult_WithMessage()
    {
        var result = _controller.Contact();

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal("Your contact page.", _controller.ViewBag.Message);
    }

    [Fact]
    public void Error_ReturnsViewResult()
    {
        var result = _controller.Error();
        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void Unauthorized_ReturnsViewResult_WithMessage()
    {
        var result = _controller.Unauthorized();

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal("You don't have permission to access this resource.", _controller.ViewBag.Message);
    }

    [Fact]
    public void About_ReturnsViewWithEnrollmentDateGroups()
    {
        // Seed students with different enrollment dates
        _context.Students.AddRange(
            new Student { LastName = "A", FirstMidName = "A", EnrollmentDate = new DateTime(2023, 9, 1) },
            new Student { LastName = "B", FirstMidName = "B", EnrollmentDate = new DateTime(2023, 9, 1) },
            new Student { LastName = "C", FirstMidName = "C", EnrollmentDate = new DateTime(2024, 1, 15) }
        );
        _context.SaveChanges();

        var result = _controller.About();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(viewResult.Model);
        Assert.Equal(2, model.Count); // Two distinct enrollment dates

        var sept2023Group = model.Single(g => g.EnrollmentDate == new DateTime(2023, 9, 1));
        Assert.Equal(2, sept2023Group.StudentCount);

        var jan2024Group = model.Single(g => g.EnrollmentDate == new DateTime(2024, 1, 15));
        Assert.Equal(1, jan2024Group.StudentCount);
    }

    [Fact]
    public void About_EmptyDb_ReturnsEmptyList()
    {
        var result = _controller.About();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(viewResult.Model);
        Assert.Empty(model);
    }

    [Fact]
    public void About_AllSameDate_ReturnsSingleGroup()
    {
        var date = new DateTime(2024, 9, 1);
        _context.Students.AddRange(
            new Student { LastName = "X", FirstMidName = "X", EnrollmentDate = date },
            new Student { LastName = "Y", FirstMidName = "Y", EnrollmentDate = date },
            new Student { LastName = "Z", FirstMidName = "Z", EnrollmentDate = date }
        );
        _context.SaveChanges();

        var result = _controller.About();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal(3, model[0].StudentCount);
        Assert.Equal(date, model[0].EnrollmentDate);
    }
}

