using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;
    private readonly NotificationService _notificationService;

    public NotificationsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new NotificationsController(_context);
        _notificationService = new NotificationService();
        // Drain the static queue to start clean
        while (_notificationService.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain queue after test
        while (_notificationService.ReceiveNotification() != null) { }
        _controller.Dispose();
        _context.Dispose();
        _notificationService.Dispose();
    }

    [Fact]
    public void Index_ReturnsViewResult()
    {
        var result = _controller.Index();
        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
    {
        var result = _controller.GetNotifications();

        Assert.IsType<JsonResult>(result);
        var value = result.Value;
        // Verify the anonymous object has expected shape using reflection
        var successProp = value.GetType().GetProperty("success");
        Assert.NotNull(successProp);
        Assert.True((bool)successProp.GetValue(value));

        var countProp = value.GetType().GetProperty("count");
        Assert.NotNull(countProp);
        Assert.Equal(0, (int)countProp.GetValue(value));
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsUpTo10()
    {
        // Enqueue 12 notifications via the static queue
        for (int i = 0; i < 12; i++)
        {
            _notificationService.SendNotification("Test", i.ToString(), $"Entity{i}", EntityOperation.CREATE, "TestUser");
        }

        var result = _controller.GetNotifications();

        var value = result.Value;
        var countProp = value.GetType().GetProperty("count");
        var count = (int)countProp.GetValue(value);
        Assert.Equal(10, count); // Capped at 10

        var notificationsProp = value.GetType().GetProperty("notifications");
        var notifications = (List<Notification>)notificationsProp.GetValue(value);
        Assert.Equal(10, notifications.Count);
    }

    [Fact]
    public void GetNotifications_WithFewNotifications_ReturnsAll()
    {
        _notificationService.SendNotification("Student", "1", "Alice", EntityOperation.CREATE, "Admin");
        _notificationService.SendNotification("Course", "2", "Math", EntityOperation.UPDATE, "Admin");

        var result = _controller.GetNotifications();

        var value = result.Value;
        var countProp = value.GetType().GetProperty("count");
        Assert.Equal(2, (int)countProp.GetValue(value));
    }

    [Fact]
    public void GetNotifications_DequeuesFromQueue()
    {
        _notificationService.SendNotification("Student", "1", EntityOperation.CREATE);

        // First call should dequeue
        _controller.GetNotifications();

